export const notificationRouter = Router();
notificationRouter.get(['/','/my-notifications'], requireAuth, async (req,res) => {
  const {page,limit,skip}=pagination(req.query as Record<string,unknown>);
  const filter={$or:[{user:req.user._id},{userId:req.user._id}]};
  const [rows,total]=await Promise.all([Notification.find(filter).sort({createdAt:-1}).skip(skip).limit(limit),Notification.countDocuments(filter)]);
  return sendList(res,rows.map((n:any)=>({id:String(n._id),_id:String(n._id),title:n.title??n.subject??'Notification',message:n.message??n.body??'',type:n.type??'system',isRead:n.isRead===true||n.read===true,createdAt:n.createdAt??n.timestamp??null,metadata:n.metadata??null})),page,limit,total);
});
