export const messagingRouter=Router();
async function conversationSummaries(rows:any[],user:any){
  const farmerView=normalizeRole(user.role)==='farmer';
  return Promise.all(rows.map(async(c:any)=>{
    const participants=await Promise.all((c.participants??[]).map(async(id:any)=>{const u=await User.findById(id);return u?{...displayUser(u),id:String(u._id)}:null;}));
    const other=participants.find((person:any)=>person?.id!==String(user._id))??null;
    const messages=await Message.find({conversation:c._id}).sort({createdAt:1}).limit(500);
    const first=messages[0];
    const ownReply=[...messages].reverse().find((m:any)=>String(m.sender)===String(user._id)&&String(m.sender)!==String(first?.sender));
    const otherReply=[...messages].reverse().find((m:any)=>String(m.sender)!==String(user._id)&&String(m.sender)!==String(first?.sender));
    const reply=farmerView?ownReply:otherReply;
    const product=c.productId?await Product.findById(c.productId).select('name title').lean():null;
    const state=String(c.status??(messages.length>1?'replied':'open')).toLowerCase();
    return{id:String(c._id),conversationId:String(c._id),participants:participants.filter(Boolean),recipient:other,user:other,otherParty:other,product:product?{id:String((product as any)._id),name:(product as any).name??(product as any).title??null}:null,listingName:(product as any)?.name??(product as any)?.title??null,message:first?.text??first?.message??'',reply:reply?.text??reply?.message??'',messages:messages.map((m:any)=>({id:String(m._id),senderId:String(m.sender),fromCurrentUser:String(m.sender)===String(user._id),text:m.text??m.message??'',createdAt:m.createdAt??null})),status:state==='closed'?'Closed':state==='replied'?'Replied':'Open',lastMessage:messages.length?{text:messages.at(-1)?.text??messages.at(-1)?.message??'',createdAt:messages.at(-1)?.createdAt??null}:null,createdAt:first?.createdAt??c.createdAt??null,updatedAt:c.lastMessageAt??c.updatedAt??null};
  }));
}
messagingRouter.get('/conversations',requireAuth,async(req,res)=>{
  const rows=await Conversation.find({participants:req.user._id}).sort({lastMessageAt:-1}).limit(100);
  const output=await conversationSummaries(rows,req.user);
  return sendData(res,{conversations:output});
});
messagingRouter.get('/unread-count',requireAuth,async(req,res)=>{const count=await Notification.countDocuments({$or:[{user:req.user._id},{userId:req.user._id}],type:'message',isRead:{$ne:true},read:{$ne:true}});return sendData(res,{count});});
messagingRouter.patch('/conversations/:id/status',requireAuth,async(req,res)=>{requireRole(req,['farmer']);const id=objectId(req.params.id);const status=parseBody(z.object({status:z.enum(['replied','closed'])}),req.body).status;const conversation=await Conversation.findOne({_id:id,participants:req.user._id});if(!conversation)throw new HttpError(404,'Conversation not found.','CONVERSATION_NOT_FOUND');if(conversation.productId){const product=await Product.findById(conversation.productId);if(!product)throw new HttpError(404,'The listing for this conversation no longer exists.','LISTING_NOT_FOUND');const owner=product.farmer??product.sellerId??product.seller;if(String(owner)!==String(req.user._id))throw new HttpError(403,'You can update only conversations about your own listings.','FORBIDDEN');}if(String(conversation.status).toLowerCase()==='closed'&&status!=='closed')throw new HttpError(409,'A closed conversation cannot be reopened from this action.','INVALID_CONVERSATION_TRANSITION');if(status==='replied'&&!await Message.exists({conversation:id,sender:req.user._id}))throw new HttpError(409,'Send a reply before marking this inquiry as replied.','REPLY_REQUIRED');conversation.status=status;conversation.statusUpdatedAt=new Date();conversation.statusUpdatedBy=req.user._id;await conversation.save();await writeAudit({actor:req.user._id,action:'conversation.status_updated',resource:'conversation',resourceId:String(id),metadata:{status}});return sendData(res,{id:String(id),status:status==='closed'?'Closed':'Replied'});});
async function listConversationMessages(req:any,res:any){
  const conversationId=objectId(req.query.conversationId??req.query.chatId,'conversationId');
  const conversation=await Conversation.findOne({_id:conversationId,participants:req.user._id});if(!conversation)throw new HttpError(404,'Conversation not found.','CONVERSATION_NOT_FOUND');
  const rows=await Message.find({conversation:conversationId}).sort({createdAt:1}).limit(500);
  return sendData(res,{messages:rows.map((m:any)=>({id:String(m._id),conversationId:String(m.conversation),senderId:String(m.sender),text:m.text??m.message??'',createdAt:m.createdAt??null}))});
}
messagingRouter.get('/',requireAuth,async(req,res)=>{
  if(req.query.chatId||req.query.conversationId)return listConversationMessages(req,res);
  const rows=await Conversation.find({participants:req.user._id}).sort({lastMessageAt:-1}).limit(100);return sendData(res,await conversationSummaries(rows,req.user));
});
messagingRouter.get('/messages',requireAuth,listConversationMessages);
messagingRouter.post(['/send-message','/messages'],requireAuth,async(req,res)=>{
  requireRole(req,['farmer','buyer']);
  const body=parseBody(z.object({recipientId:z.string().optional(),conversationId:z.string().optional(),chatId:z.string().optional(),productId:z.string().optional(),message:z.string().trim().min(1).max(5000).optional(),text:z.string().trim().min(1).max(5000).optional()}),req.body);
  const text=body.text??body.message;if(!text)throw new HttpError(422,'Enter a message.','MESSAGE_REQUIRED','message');
  let conversation:any;let linkedProduct:any=null;
  const conversationId=body.conversationId??body.chatId;
  if(conversationId){conversation=await Conversation.findOne({_id:objectId(conversationId),participants:req.user._id});if(!conversation)throw new HttpError(404,'Conversation not found.','CONVERSATION_NOT_FOUND');if(String(conversation.status??'').toLowerCase()==='closed')throw new HttpError(409,'This conversation is closed.','CONVERSATION_CLOSED');if(normalizeRole(req.user.role)==='farmer'){if(!conversation.productId)throw new HttpError(403,'A farmer can reply only to an inquiry about an owned listing.','FORBIDDEN');const owned=await Product.exists({_id:conversation.productId,isDeleted:{$ne:true},$or:[{farmer:req.user._id},{sellerId:req.user._id}]});if(!owned)throw new HttpError(403,'You can reply only to inquiries about your own listings.','FORBIDDEN');}}
  else {
    let rawRecipient=body.recipientId;if(body.productId){linkedProduct=await Product.findById(objectId(body.productId));if(!linkedProduct||linkedProduct.isDeleted===true)throw new HttpError(404,'Listing not found.','LISTING_NOT_FOUND');rawRecipient=String(linkedProduct.farmer??linkedProduct.sellerId??linkedProduct.seller??'');}
    if(!rawRecipient)throw new HttpError(422,'Choose a recipient.','RECIPIENT_REQUIRED','recipientId');
    const recipientId=objectId(rawRecipient,'recipientId');if(String(recipientId)===String(req.user._id))throw new HttpError(422,'You cannot message yourself.','INVALID_RECIPIENT');
    if(!await User.exists({_id:recipientId,isActive:{$ne:false},isDeleted:{$ne:true}}))throw new HttpError(404,'Recipient not found.','RECIPIENT_NOT_FOUND');
    const participants=[req.user._id,recipientId];const conversationFilter:any={participants:{$all:participants,$size:2}};if(linkedProduct)conversationFilter.productId=linkedProduct._id;conversation=await Conversation.findOne(conversationFilter);
    if(!conversation)conversation=await Conversation.create({participants,...(linkedProduct?{productId:linkedProduct._id}:{}),createdBy:req.user._id,status:'open',lastMessageAt:new Date()});
  }
  const msg=await Message.create({conversation:conversation._id,sender:req.user._id,text,createdAt:new Date()});const sentAt=new Date();conversation.lastMessageAt=sentAt;conversation.status=normalizeRole(req.user.role)==='farmer'?'replied':'open';await conversation.save();
  const other=(conversation.participants??[]).find((id:any)=>String(id)!==String(req.user._id));if(other)await createInAppNotification(other,'message','New message','You have received a new message.',{conversationId:String(conversation._id)});
  const summary=(await conversationSummaries([conversation],req.user))[0];
  return sendData(res,{id:String(msg._id),conversationId:String(conversation._id),senderId:String(req.user._id),text,status:conversation.status==='replied'?'Replied':'Open',listingName:linkedProduct?.name??linkedProduct?.title??null,createdAt:msg.createdAt,conversation:summary},201);
});

export const marketIntelligenceRouter=Router();
const safeRegex=(value:unknown)=>String(value).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
async function listMarketIntelligence(req:any,res:any){
  const {page,limit,skip}=pagination(req.query as Record<string,unknown>);
  const filter:any=verifiedMarketObservationQuery();
  if(req.query.produce)filter.$and.push({$or:[{produce:{$regex:safeRegex(req.query.produce),$options:'i'}},{crop:{$regex:safeRegex(req.query.produce),$options:'i'}}]});
  if(req.query.county)filter.$and.push({$or:[{county:{$regex:safeRegex(req.query.county),$options:'i'}},{location:{$regex:safeRegex(req.query.county),$options:'i'}}]});
  if(req.query.priceType==='wholesale'||req.query.priceType==='retail')filter.$and.push({priceType:req.query.priceType});
  const chooseText=(fields:string[])=>({$switch:{branches:fields.map((field)=>({case:{$and:[{$eq:[{$type:`$${field}`},'string']},{$ne:[`$${field}`,'']}]},then:`$${field}`})),default:null}});
  const [result]=await MarketPrice.aggregate([
    {$match:filter},{$sort:{observedAt:-1,_id:1}},{$addFields:{_commodity:chooseText(['produce','crop']),_location:chooseText(['location','county']),_unit:chooseText(['unit','measurementUnit']),_source:chooseText(['sourceName','source','provider']),_sourceReference:{$ifNull:['$sourceReference',{$ifNull:['$sourceUrl',null]}]},_priceType:{$ifNull:['$priceType',null]}}},
    {$group:{_id:{produce:{$toLower:'$_commodity'},market:{$toLower:'$market'},location:{$toLower:'$_location'},price:'$price',currency:'$currency',unit:{$toLower:'$_unit'},observedAt:'$observedAt',source:{$toLower:'$_source'},sourceReference:'$_sourceReference',priceType:'$_priceType'},record:{$first:'$$ROOT'}}},
    {$replaceRoot:{newRoot:'$record'}},{$sort:{observedAt:-1,_id:1}},{$facet:{data:[{$skip:skip},{$limit:limit}],total:[{$count:'count'}]}},
  ]);
  const valid=deduplicateMarketObservations((result?.data??[]).map((row:any)=>marketObservationToApi(row)).filter(Boolean));
  const total=Number(result?.total?.[0]?.count??0);const current=valid.some((row:any)=>row.freshness==='current');const stale=valid.length>0&&!current;
  const availability=current?'available':stale?'stale':'unavailable';
  return res.json({success:true,message:current?'OK':stale?'Only stale verified market observations are available.':'Verified market data is unavailable.',data:valid,meta:{page,limit,total,pages:Math.ceil(total/limit),availability}});
}
marketIntelligenceRouter.get('/',listMarketIntelligence);
marketIntelligenceRouter.get('/prices',listMarketIntelligence);
marketIntelligenceRouter.get('/prices/:produce',async(req,res)=>{req.query.produce=req.params.produce;return listMarketIntelligence(req,res);});
marketIntelligenceRouter.get('/status',async(_req,res)=>{
  const now=new Date();const cutoff=new Date(now.getTime()-7*24*60*60*1000);
  const filter:any=verifiedMarketObservationQuery(now);
  const freshFilter={...filter,$and:[...filter.$and,{observedAt:{$gte:cutoff,$lte:now}}]};
  const [verifiedObservationCount,freshObservationCount]=await Promise.all([
    MarketPrice.countDocuments(filter),
    MarketPrice.countDocuments(freshFilter),
  ]);
  const providerCredentialsPresent=Boolean(process.env.MARKET_DATA_PROVIDER_URL&&process.env.MARKET_DATA_PROVIDER_KEY);
  return sendData(res,{available:freshObservationCount>0,reason:freshObservationCount?'':verifiedObservationCount?'Only stale verified market observations are on record.':'No verified market observations are available.',verifiedObservationCount,freshObservationCount,staleObservationCount:Math.max(verifiedObservationCount-freshObservationCount,0),providerCredentialsPresent,providerIntegrationAvailable:false});
});

