async function listActivity(req:any,res:any){
  const {page,limit,skip}=pagination(req.query as Record<string,unknown>);
  const query=parseBody(z.object({search:z.string().trim().max(80).optional(),action:z.string().trim().max(100).optional(),resource:z.string().trim().max(100).optional(),actor:z.string().trim().max(100).optional(),actorId:z.string().optional(),outcome:z.enum(['success','denied','failure']).optional(),from:z.iso.date().optional(),to:z.iso.date().optional()}),req.query);
  if(query.from&&query.to&&query.from>query.to)throw new HttpError(422,'The start date must be on or before the end date.','INVALID_DATE_RANGE');
  const filter:any={};if(query.action)filter.action=query.action;if(query.resource)filter.resource=query.resource;if(query.outcome)filter.outcome=query.outcome;if(query.actorId)filter.actor=objectId(query.actorId,'actorId');
  if(query.actor){const expression={$regex:safeRegex(query.actor),$options:'i'};const actors=await User.find({$or:[{email:expression},{fullName:expression},{firstName:expression},{lastName:expression}]}).select('_id').limit(100).lean();filter.actor={$in:actors.map((actor:any)=>actor._id)};}
  if(query.from||query.to){const end=query.to?new Date(`${query.to}T00:00:00.000Z`):new Date();if(query.to)end.setUTCDate(end.getUTCDate()+1);filter.createdAt={$gte:query.from?new Date(`${query.from}T00:00:00.000Z`):new Date(0),$lt:end};}
  if(query.search){const expression={$regex:safeRegex(query.search),$options:'i'};const matchingActors=await User.find({$or:[{email:expression},{fullName:expression},{firstName:expression},{lastName:expression}]}).select('_id').limit(100).lean();filter.$and=[...(filter.$and??[]),{$or:[{action:expression},{resource:expression},{resourceId:expression},...(matchingActors.length?[{actor:{$in:matchingActors.map((user:any)=>user._id)}}]:[])]}];}
  const [rows,total]=await Promise.all([AuditLog.find(filter).sort({createdAt:-1,_id:-1}).skip(skip).limit(limit),AuditLog.countDocuments(filter)]);
  const actorIds=rows.map((row:any)=>row.actor).filter(Boolean);const actors=actorIds.length?await User.find({_id:{$in:actorIds}}).select('email fullName firstName lastName role').lean():[];const actorMap=new Map(actors.map((actor:any)=>[String(actor._id),displayUser(actor)]));
  return sendList(res,rows.map((row:any)=>({id:String(row._id),action:row.action,resource:row.resource,resourceId:row.resourceId??null,outcome:row.outcome??'success',actor:row.actor?actorMap.get(String(row.actor))??null:null,createdAt:row.createdAt??null,metadata:row.metadata??{}})),page,limit,total);
}
