adminPlatformRouter.get('/support',requirePermission('support.manage'),async(req,res)=>{const {page,limit,skip}=pagination(req.query as Record<string,unknown>);const filter:any={};if(['open','response_recorded','replied','in_progress','resolved','closed'].includes(String(req.query.status)))filter.status=String(req.query.status);const search=String(req.query.search??'').trim().slice(0,80);if(search){const expression={$regex:safeRegex(search),$options:'i'};filter.$or=[{name:expression},{email:expression},{subject:expression},{message:expression},{category:expression},{userType:expression}];}const [rows,total]=await Promise.all([ContactMessage.find(filter).sort({createdAt:-1}).skip(skip).limit(limit),ContactMessage.countDocuments(filter)]);return sendList(res,rows.map((x:any)=>({id:String(x._id),_id:String(x._id),name:x.name,email:x.email,subject:x.subject,message:x.message,category:x.category??null,userType:x.userType??null,status:x.status??'open',assignedTo:x.assignedTo?String(x.assignedTo):null,createdAt:x.createdAt??null})),page,limit,total);});
adminPlatformRouter.get('/notifications',requirePermission('announcements.manage'),async(req,res)=>{const{page,limit,skip}=pagination(req.query as Record<string,unknown>);const search=String(req.query.search??'').trim().slice(0,80);const filter:any={};if(search){const expression={$regex:safeRegex(search),$options:'i'};const users=await User.find({$or:[{email:expression},{fullName:expression},{firstName:expression},{lastName:expression}]}).select('_id').limit(100).lean();const userIds=users.map((user:any)=>user._id);filter.$or=[{title:expression},{message:expression},...(userIds.length?[{user:{$in:userIds}},{userId:{$in:userIds}}]:[])];}const[rows,total]=await Promise.all([Notification.find(filter).sort({createdAt:-1,_id:-1}).skip(skip).limit(limit),Notification.countDocuments(filter)]);const userIds=rows.flatMap((row:any)=>[row.user,row.userId].filter(Boolean));const owners=userIds.length?await User.find({_id:{$in:userIds}}).select('fullName firstName lastName email').lean():[];const ownerById=new Map(owners.map((user:any)=>[String(user._id),user]));return sendList(res,rows.map((row:any)=>{const recipient=ownerById.get(String(row.user??row.userId)) as any;return{id:String(row._id),recipient:recipient?.email??null,recipientName:recipient?.fullName??([recipient?.firstName,recipient?.lastName].filter(Boolean).join(' ')||null),title:row.title??row.subject??null,message:row.message??row.body??null,type:row.type??'system',isRead:row.isRead===true||row.read===true,createdAt:row.createdAt??row.timestamp??null};}),page,limit,total);});
adminPlatformRouter.post('/notifications',requirePermission('announcements.manage'),async(req,res)=>{const body=parseBody(z.object({email:z.string().trim().email().max(254),title:z.string().trim().min(2).max(160),message:z.string().trim().min(2).max(2000)}),req.body);const user=await User.findOne({email:body.email.toLowerCase(),isDeleted:{$ne:true}}).select('_id');if(!user)throw new HttpError(404,'No active account matches that email address.','NOTIFICATION_RECIPIENT_NOT_FOUND');const createdAt=new Date();const row=await Notification.create({user:user._id,userId:user._id,title:body.title,message:body.message,type:'admin',isRead:false,createdAt});await writeAudit({actor:req.user._id,action:'notification.created',resource:'notification',resourceId:String(row._id),metadata:{recipient:String(user._id)}});return sendData(res,{id:String(row._id),recipient:body.email.toLowerCase(),createdAt},201);});
adminPlatformRouter.get('/support/assignees',requirePermission('support.manage'),async(_req,res)=>{const users=await User.find({role:{$in:['admin','super_admin']},isActive:{$ne:false},isDeleted:{$ne:true}}).sort({fullName:1,email:1}).select('email fullName firstName lastName role');return sendData(res,{assignees:users.map(displayUser)});});
adminPlatformRouter.get('/support/:id',requirePermission('support.manage'),async(req,res)=>{const row:any=await ContactMessage.findById(objectId(req.params.id)).lean();if(!row)throw new HttpError(404,'Support message not found.','SUPPORT_NOT_FOUND');const authorIds=(Array.isArray(row.replies)?row.replies:[]).map((reply:any)=>reply.author).filter(Boolean);const ids=[row.assignedTo,row.handledBy,...authorIds].filter(Boolean);const users=ids.length?await User.find({_id:{$in:ids}}).select('email fullName firstName lastName role').lean():[];const byId=new Map(users.map((user:any)=>[String(user._id),displayUser(user)]));return sendData(res,{id:String(row._id),_id:String(row._id),name:row.name??null,email:row.email??null,subject:row.subject??null,message:row.message??null,category:row.category??null,userType:row.userType??null,status:row.status??'open',assignedTo:row.assignedTo?byId.get(String(row.assignedTo))??{id:String(row.assignedTo),fullName:null,email:null}:null,handledBy:row.handledBy?byId.get(String(row.handledBy))??{id:String(row.handledBy),fullName:null,email:null}:null,replies:(Array.isArray(row.replies)?row.replies:[]).map((reply:any)=>({id:reply._id?String(reply._id):null,body:typeof reply.body==='string'?reply.body:'',author:reply.author?byId.get(String(reply.author))??{id:String(reply.author),fullName:null,email:null}:null,createdAt:reply.createdAt??null,deliveryStatus:reply.deliveryStatus??'unknown',deliveredAt:reply.deliveredAt??null})),createdAt:row.createdAt??null,updatedAt:row.updatedAt??null});});
adminPlatformRouter.patch('/support/:id/assignment',requirePermission('support.manage'),async(req,res)=>{const id=objectId(req.params.id);const body=parseBody(z.object({assignedTo:z.string().nullable()}),req.body);const assignedTo=body.assignedTo===null?null:objectId(body.assignedTo,'assignedTo');const row=await ContactMessage.findById(id).select('_id');if(!row)throw new HttpError(404,'Support message not found.','SUPPORT_NOT_FOUND');let assignee:any=null;if(assignedTo){assignee=await User.findOne({_id:assignedTo,role:{$in:['admin','super_admin']},isActive:{$ne:false},isDeleted:{$ne:true}}).select('email fullName firstName lastName role');if(!assignee)throw new HttpError(422,'Choose an active administrator account.','INVALID_SUPPORT_ASSIGNEE','assignedTo');}await ContactMessage.updateOne({_id:id},{$set:{assignedTo,assignedAt:new Date(),assignedBy:req.user._id,updatedAt:new Date()}});await writeAudit({actor:req.user._id,action:'support.assigned',resource:'contact-message',resourceId:String(id),metadata:{assignedTo:assignedTo?String(assignedTo):null}});return sendData(res,{id:String(id),assignedTo:assignee?displayUser(assignee):null});});
adminPlatformRouter.post('/support/:id/reply',requirePermission('support.manage'),async(req,res)=>{const id=objectId(req.params.id);const body=parseBody(z.object({reply:z.string().trim().min(1).max(5000)}),req.body);const row=await ContactMessage.findById(id);if(!row)throw new HttpError(404,'Support message not found.','SUPPORT_NOT_FOUND');if(typeof row.email!=='string'||!z.email().safeParse(row.email).success)throw new HttpError(422,'This contact message has no valid reply address.','INVALID_REPLY_ADDRESS');const replyId=new mongoose.Types.ObjectId();const createdAt=new Date();await ContactMessage.updateOne({_id:id},{$push:{replies:{_id:replyId,body:body.reply,author:req.user._id,createdAt,deliveryStatus:'pending'}},$set:{handledBy:req.user._id,updatedAt:createdAt}});let deliveryStatus:'sent'|'not_configured'|'failed'='not_configured';if(process.env.SMTP_HOST&&process.env.SMTP_FROM){try{await sendSupportReplyEmail(row.email,typeof row.subject==='string'?row.subject:'',body.reply);deliveryStatus='sent';}catch{deliveryStatus='failed';}}const deliveredAt=deliveryStatus==='sent'?new Date():null;await ContactMessage.updateOne({_id:id,'replies._id':replyId},{$set:{'replies.$.deliveryStatus':deliveryStatus,'replies.$.deliveredAt':deliveredAt,status:deliveryStatus==='sent'?'replied':'response_recorded',updatedAt:new Date()}});await writeAudit({actor:req.user._id,action:'support.reply_recorded',resource:'contact-message',resourceId:String(id),metadata:{deliveryStatus}});return sendData(res,{id:String(id),replyId:String(replyId),deliveryStatus,message:deliveryStatus==='sent'?'Reply sent and recorded.':deliveryStatus==='failed'?'Reply was saved, but email delivery failed.':'Reply was saved; email delivery is unavailable until SMTP is configured.'});});
adminPlatformRouter.patch('/support/:id',requirePermission('support.manage'),async(req,res)=>{const id=objectId(req.params.id);const body=parseBody(z.object({status:z.enum(['open','in_progress','resolved','closed']),resolutionNote:z.string().trim().max(1000).optional()}),req.body);const row=await ContactMessage.findByIdAndUpdate(id,{$set:{...body,handledBy:req.user._id,updatedAt:new Date()}},{returnDocument:'after'});if(!row)throw new HttpError(404,'Support message not found.','SUPPORT_NOT_FOUND');await writeAudit({actor:req.user._id,action:'support.updated',resource:'contact-message',resourceId:String(id),metadata:{status:body.status}});return sendData(res,{id:String(row._id),status:row.status});});
adminPlatformRouter.get('/withdrawals',requirePermission('payments.read'),async(req,res)=>{const {page,limit,skip}=pagination(req.query as Record<string,unknown>);const clauses:any[]=[];if(req.query.status)clauses.push({status:String(req.query.status)});const search=String(req.query.search??'').trim().slice(0,80);if(search){const expression={$regex:safeRegex(search),$options:'i'};const matchingUsers=await User.find({$or:[{fullName:expression},{firstName:expression},{lastName:expression},{email:expression}]}).select('_id').limit(100).lean();const ids=matchingUsers.map((u:any)=>u._id);const searchOr:any[]=[{reference:expression},{transactionId:expression},{method:expression},{paymentMethod:expression},{status:expression}];if(ids.length)searchOr.push({sellerId:{$in:ids}},{userId:{$in:ids}});clauses.push({$or:searchOr});}const filter=clauses.length?{$and:clauses}:{};const [rows,total]=await Promise.all([Withdraw.find(filter).sort({createdAt:-1}).skip(skip).limit(limit).lean(),Withdraw.countDocuments(filter)]);const ownerIds=rows.flatMap((row:any)=>[row.sellerId,row.userId].map((value:any)=>{const raw=value&&typeof value==='object'&&value._id?value._id:value;if(!raw||!mongoose.Types.ObjectId.isValid(String(raw)))return null;return new mongoose.Types.ObjectId(String(raw));}).filter(Boolean));const owners=ownerIds.length?await User.find({_id:{$in:ownerIds}}).select('fullName firstName lastName email role').lean():[];const ownerById=new Map(owners.map((user:any)=>[String(user._id),user]));return sendList(res,rows.map((row:any)=>{const rawOwner=row.sellerId??row.userId;const ownerId=rawOwner&&typeof rawOwner==='object'&&rawOwner._id?String(rawOwner._id):rawOwner?String(rawOwner):'';const owner:any=ownerById.get(ownerId);const fullName=(owner?.fullName??owner?.name??[owner?.firstName,owner?.lastName].filter(Boolean).join(' '))||null;const ownerView=owner?{id:String(owner._id),fullName:fullName||owner.email||null,email:owner.email??null}:null;return{id:String(row._id),_id:String(row._id),sellerId:owner?String(owner._id):null,userId:ownerView,user:ownerView,farmer:ownerView,amount:Number.isFinite(row.amount)?Number(row.amount):null,amountCents:Number.isFinite(row.amountCents)?Number(row.amountCents):null,currency:typeof row.currency==='string'?row.currency:null,method:row.method??row.paymentMethod??null,status:row.status??null,createdAt:row.createdAt??null};}),page,limit,total);});
